<script setup lang="ts">
import KnowledgeMotion from './KnowledgeMotion.vue';
import {ref,computed,watch,nextTick,onBeforeUnmount} from 'vue';import SymmetryLab from './SymmetryLab.vue';
import {articles,glossary,craftSteps} from './knowledge';
const showAll=ref(false);const categories=['全部',...new Set(articles.map(a=>a.section))];const publicSources=[...new Map(articles.flatMap(a=>a.source_refs||[]).map(s=>[s.url,s])).values()];const learningPaths=[{id:'auspicious-rebus',label:'从寓意入门',text:'看懂图案怎样说祝福',icon:'意'},{id:'weihai-tin',label:'从工艺入门',text:'理解纹面为什么要适器',icon:'锡'},{id:'living-heritage',label:'从传承入门',text:'让来源、人的参与与创作相连',icon:'传'}];
const props=defineProps<{initialArticle?:string}>();const emit=defineEmits(['pattern','create','article-close']);const section=ref('全部'),query=ref(''),article=ref<any>(null),craft=ref(0),answer=ref<number|null>(null);const visible=computed(()=>articles.filter(a=>(section.value==='全部'||a.section===section.value)&&(!query.value||(a.title+a.body.join('')+a.pattern+(a.source_refs||[]).map(s=>s.organization+s.title).join('')).includes(query.value))));watch(article,async (a,previous)=>{document.body.style.overflow=a?'hidden':'';if(!a&&previous)emit('article-close');if(a){await nextTick();document.querySelector<HTMLElement>('.reading-modal')?.focus()}});
watch(()=>props.initialArticle,id=>{if(id)article.value=articles.find(a=>a.id===id)||null},{immediate:true});
function createFromArticle(){const id=article.value?.pattern,articleId=article.value?.id;article.value=null;emit('create',id,articleId)}
function openArchive(){const id=article.value?.pattern;article.value=null;emit('pattern',id)}
function readRandom(){const pool=visible.value.length?visible.value:articles;article.value=pool[Math.floor(Math.random()*pool.length)]}
function trap(event:KeyboardEvent){if(event.key!=='Tab')return;const elements=Array.from(document.querySelectorAll<HTMLElement>('.reading-modal button,.reading-modal a'));if(!elements.length)return;const first=elements[0],last=elements[elements.length-1];if(event.shiftKey&&(document.activeElement===first||document.activeElement?.classList.contains('reading-modal'))){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
onBeforeUnmount(()=>{document.body.style.overflow=''});
const terms=computed(()=>glossary.filter(g=>!query.value||(g.word+g.text).includes(query.value)));
</script><template><main class="knowledge-page"><KnowledgeMotion/><section class="knowledge-intro"><div><p class="kicker">A LIVING BOOK OF PATTERNS / 纹样书房</p><h1>读纹如读信，<br><em>字字有来处。</em></h1><p>一朵莲为何寄托清正，一道回纹怎样表达绵延？<br>循着形与意的线索，走进中国纹样的日常世界。</p></div><div class="book-cover"><div class="book-lines"></div><span class="book-vertical">观纹 · 知意 · 识器 · 入艺</span><span class="book-title">纹<br>样<br>小<br>记</span><small>锡语华纹 · 文化读本</small><div class="book-mark">卷一<br>入门</div></div></section><div class="knowledge-nav"><div><button v-for="s in categories" :class="{active:section===s}" @click="section=s">{{s}}</button></div><div class="knowledge-search-actions"><input v-model="query" placeholder="检索知识与术语" aria-label="检索知识库"><button class="knowledge-random" @click="readRandom">随读一篇 ↗</button></div></div><section class="knowledge-start"><div><p class="kicker">循据而学 · 由知入造</p><h2>先找一个入口，<em>再读一层深意。</em></h2><p>{{articles.length}} 篇主题阅读，连接纹样档案、构图实验与器物创作。</p></div><div class="knowledge-paths"><button v-for="path in learningPaths" @click="article=articles.find(a=>a.id===path.id)"><span>{{path.icon}}</span><div><small>{{path.label}}</small><h3>{{path.text}}</h3></div><b>↗</b></button></div></section><section class="article-grid"><button v-for="(a,i) in (showAll?visible:visible.slice(0,6))" class="article-card" @click="article=a"><div :class="['article-illustration','illustration-'+a.id]"><span>{{a.symbol}}</span><svg viewBox="0 0 300 200" aria-hidden="true"><g v-if="['symmetry','star'].includes(a.id)" transform="translate(150 100)"><path v-for="n in 8" :transform="`rotate(${n*45})`" d="M0 -70 Q25 -30 0 0 Q-25 -30 0 -70Z"/><circle r="82"/><circle r="57"/></g><g v-else-if="a.id==='lotus'" transform="translate(150 100)"><path v-for="n in 4" :transform="`rotate(${n*90})`" d="M0 0 C-55 -45 -40 -100 0 -72 C40 -100 55 -45 0 0Z"/></g><g v-else><circle cx="150" cy="100" r="67"/><path d="M75 100H225M150 25V175M95 45L205 155M95 155L205 45"/><rect x="101" y="51" width="98" height="98" transform="rotate(45 150 100)"/></g></svg></div><div class="article-info"><small>{{a.section}} <i>·</i> {{a.time}}</small><span class="knowledge-source-badge">{{a.source_refs?.[0]?.organization||'项目标注资料'}}</span><h3>{{a.title}}</h3><p>{{a.deck}}</p><span>展开阅读 ↗</span></div></button><p v-if="!visible.length" class="empty">暂未找到相关文章，可换一个关键词。</p></section><button class="knowledge-more" v-if="visible.length>6" @click="showAll=!showAll">{{showAll?'收起文章':'查看全部知识 · '+visible.length+' 篇'}}</button><SymmetryLab/><section class="craft-exhibit"><div class="section-title"><div><p class="kicker">FROM A LINE TO A LIFE / 一纹入器</p><h2>从纹样到器物，<em>手艺如何接力？</em></h2></div><span class="muted">点击工序，走近制作逻辑</span></div><div class="craft-track"><button v-for="(s,i) in craftSteps" :class="{active:craft===i,past:craft>i}" @click="craft=i"><span>{{s.icon}}</span><small>0{{i+1}} / {{s.name}}</small></button></div><div class="craft-story"><div class="craft-big-symbol">{{craftSteps[craft].icon}}<span class="engraving-orbit"></span></div><div :key="craft" class="craft-story-copy"><p class="kicker">{{craftSteps[craft].name}} / 0{{craft+1}}</p><h3>{{craftSteps[craft].title}}</h3><p>{{craftSteps[craft].desc}}</p><small>{{craftSteps[craft].detail}}</small><p class="source-inline">依据：《序言2—技术基础》的转译流程整理；不同工坊的实际工序会有差异。</p></div></div></section><section class="glossary-section"><div><p class="kicker">A SMALL DICTIONARY / 纹样辞笺</p><h2>先懂几个词，<br>再看一幅纹。</h2></div><div class="glossary-grid"><article v-for="g in terms"><span>{{g.type}}</span><h3>{{g.word}}</h3><p>{{g.text}}</p></article></div></section><section class="knowledge-question"><div><p class="kicker">A MOMENT TO THINK / 读纹一问</p><h2>一枚新的莲花组合，<br>是否天然拥有原纹样的全部寓意？</h2></div><div><button v-for="(a,i) in ['是，只要保留莲花外形','不一定，还要看来源与组合语境']" :class="{chosen:answer===i}" @click="answer=i">{{a}} <span>{{answer===i?(i===1?'✓':'↺'):'↗'}}</span></button><p v-if="answer!==null">{{answer===1?'是这样。':'再想一步：'}}图元可以复用，文化语义却需要证据与语境。改变组合后，应重新判断它是否仍保留原有识别度与含义。</p></div></section><section class="knowledge-source-index"><details><summary><span>循据而读 · 公开资料索引</span><small>{{publicSources.length}} 条机构来源 ↗</small></summary><p>阅读内容保存于本站，可离线浏览；原始页面链接用于进一步核对。通用知识与每份纹样档案的具体出处分别记录。</p><div><a v-for="source in publicSources" :href="source.url" target="_blank" rel="noopener noreferrer"><small>{{source.organization}}</small><h3>{{source.title}} ↗</h3><span>核对日期 {{source.accessed}}</span></a></div></details></section><section class="knowledge-end"><p>理解，是再创造的第一笔。</p><button class="primary" @click="emit('create')">带着知识去造物 ↗</button></section><Teleport to="body"><div v-if="article" class="modal-backdrop delivery-modal" @click.self="article=null" @keydown.esc="article=null" @keydown="trap"><article class="reading-modal" role="dialog" aria-modal="true" :aria-label="article.title" tabindex="-1"><button class="modal-close" @click="article=null" aria-label="关闭文章">✕</button><p class="kicker">{{article.section}} / {{article.time}}</p><span class="article-dropcap">{{article.symbol}}</span><h2>{{article.title}}</h2><p class="article-deck">{{article.deck}}</p><div v-if="article.takeaways" class="knowledge-takeaways"><article v-for="item in article.takeaways"><span>{{item.label}}</span><p>{{item.text}}</p></article></div><p v-for="p in article.body" class="article-paragraph">{{p}}</p><section v-if="article.practice" class="knowledge-practice"><span>读后试一笔</span><p>{{article.practice}}</p><small>关联练习档案：{{article.pattern}} · {{article.pattern_label}}</small></section><div class="article-source knowledge-citations"><span>循据而读</span><p>{{article.source}}</p><div v-if="article.source_refs?.length" class="knowledge-citation-links"><a v-for="source in article.source_refs" :href="source.url" target="_blank" rel="noopener noreferrer"><b>{{source.title}} ↗</b><small>{{source.organization}} · 核对日期 {{source.accessed}}</small></a></div><p v-if="article.scope" class="knowledge-scope">资料范围：{{article.scope}}</p><small v-else>本篇依据项目原始标注资料整理，具体纹样请在档案中查看原图与映射记录。</small></div><div class="knowledge-reading-actions"><button class="primary" @click="openArchive">去档案中亲眼看看 →</button><button @click="createFromArticle">带着理解，试着造物 ↗</button></div></article></div></Teleport></main></template>

